create temporary table november_tournament_seed (
  slug text not null,name text not null,city text not null,country_code text not null,category_code text not null,surface text not null,environment text not null,season_week smallint not null,phase text not null,slot_order smallint not null,is_fictional boolean not null,continent text not null
) on commit drop;
do $$ begin
 if exists (select 1 from (select distinct slug,name from november_tournament_seed) s join public.tournament_series t on lower(btrim(t.name))=lower(btrim(s.name)) and t.slug<>s.slug) then raise exception 'November tournament name conflict'; end if;
 if exists (select 1 from (select distinct slug,city from november_tournament_seed where is_fictional) s join public.tournament_series t on lower(btrim(t.city))=lower(btrim(s.city)) and t.slug<>s.slug) then raise exception 'November fictional city conflict'; end if;
 if (select count(distinct slug) from november_tournament_seed where is_fictional)<>30 then raise exception 'Expected 30 November fictional tournaments'; end if;
 if exists (select season_week from november_tournament_seed where is_fictional group by season_week having count(distinct continent)<>6 or count(distinct slug)<>6) then raise exception 'November fictional continent balance invalid'; end if;
end $$;
do $$ declare a int;b int;c int; begin select count(distinct ts.id) into a from november_tournament_seed s join public.tournament_series ts on ts.slug=s.slug; select count(*) into b from public.tournament_schedule_slots sl join public.tournament_editions e on e.id=sl.tournament_edition_id and e.season_number=1 join public.tournament_series ts on ts.id=e.tournament_series_id where ts.slug in (select distinct slug from november_tournament_seed) and sl.season_week between 44 and 48; select count(*) into c from public.tournament_world_competitions wc join public.tournament_editions e on e.id=wc.tournament_edition_id and e.season_number=1 join public.tournament_series ts on ts.id=e.tournament_series_id where ts.slug in (select distinct slug from november_tournament_seed); if a<>61 then raise exception 'Expected 61 November series, found %',a; end if; if b<>62 then raise exception 'Expected 62 November slots, found %',b; end if; if c<>122 then raise exception 'Expected 122 November competitions, found %',c; end if; end $$;