insert into public.tournament_series (slug,name,city,country_code,category_code,surface,environment) select distinct slug,name,city,country_code,category_code,surface,environment from november_tournament_seed on conflict (slug) do update set name=excluded.name,city=excluded.city,country_code=excluded.country_code,category_code=excluded.category_code,surface=excluded.surface,environment=excluded.environment,is_active=true;
insert into public.tournament_editions (tournament_series_id,season_number) select distinct ts.id,1 from november_tournament_seed s join public.tournament_series ts on ts.slug=s.slug on conflict (tournament_series_id,season_number) do nothing;
insert into public.tournament_world_competitions (tournament_edition_id,world) select distinct e.id,w.world from november_tournament_seed s join public.tournament_series ts on ts.slug=s.slug join public.tournament_editions e on e.tournament_series_id=ts.id and e.season_number=1 cross join (values ('ATP'),('WTA')) w(world) on conflict (tournament_edition_id,world) do nothing;
insert into public.tournament_schedule_slots (tournament_edition_id,calendar_month,month_week,season_week,phase,slot_order) select e.id,11,greatest(1,least(5,s.season_week-43))::smallint,s.season_week,s.phase,s.slot_order from november_tournament_seed s join public.tournament_series ts on ts.slug=s.slug join public.tournament_editions e on e.tournament_series_id=ts.id and e.season_number=1 on conflict (tournament_edition_id,season_week,phase) do update set calendar_month=excluded.calendar_month,month_week=excluded.month_week,slot_order=excluded.slot_order;
